import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { User } from '../../users/entities/user.entity';
import { AI_MODEL_STORAGE_VALUES, AiModel } from 'src/users/types';
import { UnhelpfulAnswerDescription } from '../types/unhelpfulAnswerDescription';

@Entity('ai_model_answer_reviews')
export class AiModelAnswerReview {
  @PrimaryGeneratedColumn()
  id: number;

  @ManyToOne(() => User, (user) => user.aiModelAnswerReview, {
    onDelete: 'SET NULL',
  })
  @JoinColumn({ name: 'userId' })
  user: User;

  @Column({ nullable: true })
  userId: number;

  @Column({ type: 'enum', enum: ['comment', 'dialog'] })
  type: string;

  @Column()
  isHelpful: boolean;

  @Column({
    type: 'enum',
    enum: UnhelpfulAnswerDescription,
    array: true,
    nullable: true,
  })
  unhelpfulAnswerDescriptions?: UnhelpfulAnswerDescription[];

  @Column({ type: 'text', nullable: true })
  unhelpfulComment?: string;

  @Column({ type: 'text', nullable: true })
  improvementComment?: string;

  @Column({ type: 'enum', enum: AI_MODEL_STORAGE_VALUES })
  aiModel: AiModel;

  @Column({ nullable: true, default: false })
  isRead: boolean;

  @CreateDateColumn()
  createdAt: Date;
}
